        }

        updateSinceLastItemAccountWideBuild = false;
        prevBuiltAccountWideItemList = flippingItemHandler.createAccountWideFlippingItemList(dataHandler.viewAllAccountData());;
        return prevBuiltAccountWideItemList;
    }

