package com.flippingutilities.ui.widgets;

import com.flippingutilities.controller.FlippingPlugin;
import com.flippingutilities.model.OfferEvent;
import com.flippingutilities.ui.uiutilities.CustomColors;
import com.flippingutilities.ui.uiutilities.TimeFormatters;
import lombok.Getter;
import lombok.Setter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.util.ColorUtil;

import java.awt.*;
import java.time.Instant;
import java.time.temporal.ChronoUnit;

@Slf4j
public class SlotActivityTimer
{
	//Spacing between the slot state text and the timer
	private static final String BUY_SPACER = "          ";
	private static final String SELL_SPACER = "          ";
	private static final int FONT_ID = 495;

	//The slot that this timer object embeds to
	@Getter
	private transient Widget slotWidget;
	//The widget of the text at the top of the offer slot
	private transient Widget slotStateWidget;
	//The state can be one of "Sell", "Buy" and "Empty", depending on the slot's offer state
	private transient String slotStateString;

	@Setter
	private transient FlippingPlugin plugin;
	@Setter
	private transient Client client;

	//Index of the slot widget from left to right, top to bottom. (0-7)
	@Getter
	private int slotIndex;
	private Instant lastUpdate;
	public Instant tradeStartTime;
	public OfferEvent currentOffer;
	//is true when we get an offer from when the account was logged out which means we don't know when it occurred.
	public boolean offerOccurredAtUnknownTime;

	public SlotActivityTimer(FlippingPlugin plugin, Client client, int slotIndex)
	{
		this.plugin = plugin;
		this.client = client;
		this.slotIndex = slotIndex;
	}

	public void setWidget(Widget slotWidget)
	{
		this.slotWidget = slotWidget;
		slotStateWidget = slotWidget.getChild(16);
		slotStateString = slotStateWidget.getText();
	}

	public void reset() {
		currentOffer = null;
		lastUpdate = null;
		tradeStartTime = null;
		offerOccurredAtUnknownTime = true;
	}

	public void setCurrentOffer(OfferEvent offer)
	{
		//is only given these types of offer events if they weren't empty updates
		//and there was no last offer or there was a last offer but this offer is not a dup
		if (offer.isBeforeLogin()) {
			offerOccurredAtUnknownTime = true;
			return;
		}

		offerOccurredAtUnknownTime = false;

		currentOffer = offer;
		lastUpdate = Instant.now();

		if (currentOffer.isStartOfOffer())
		{
			tradeStartTime = Instant.now();
		}
	}

	/**
	 * Updates the slot trade activity timer. It reassigns all widget field variables,
	 * as they sometimes get unloaded and therefore won't point to the right widget objects.
	 */
	public void updateTimerDisplay()
	{
		if (slotWidget == null)
		{
			return;
		}

		if (slotWidget.isHidden() || plugin.getCurrentlyLoggedInAccount() == null || currentOffer == null || offerOccurredAtUnknownTime || tradeStartTime == null)
		{
			slotStateWidget.setFontId(496);
			slotStateWidget.setXTextAlignment(1);
			return;
		}


		//Reload offerSlot widget in case it got unloaded previously. We need to do this bc the old object we have
		//doesn't respond to changes (like setText) after a ge slot redraw or some other script that fires.
		Widget offerSlot = client.getWidget(InterfaceID.GeOffers.INDEX).getStaticChildren()[slotIndex + 1];

		//Ideally this shouldn't be triggered, but just in case.
		if (offerSlot == null)
		{
			return;
		}

		//Reassign widgets
		slotWidget = offerSlot;
		slotStateWidget = slotWidget.getChild(16);
		slotStateString = slotStateWidget.getText();

		if (!isSlotFilled())
		{
			//should i set current offer to null?
			//The slot hasn't been filled with an offer, so default to Jagex format.
			slotStateWidget.setText("Empty");
			slotStateWidget.setFontId(496);
			slotStateWidget.setXTextAlignment(1);
			return;
		}

		setText(createFormattedTimeString());
		slotStateWidget.setFontId(FONT_ID);
		slotStateWidget.setXTextAlignment(0);
	}

	/**
	 * Appends the offer state text widget with the up-to-date time string.
	 *
	 * @param timeString Formatted timer string.
	 */
	private void setText(String timeString)
	{
		String spacer;
		Color stateTextColor;

		//switching comps, going on mobile, etc can leave a stale offer in there, so we have to verify using the actual
		//offer from the client.
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		GrandExchangeOffer clientOffer = offers[slotIndex];
		if (clientOffer.getState() == GrandExchangeOfferState.BOUGHT || clientOffer.getState() == GrandExchangeOfferState.BUYING || clientOffer.getState() == GrandExchangeOfferState.CANCELLED_BUY) {
			slotStateString = "Buy";
			spacer = BUY_SPACER;
			stateTextColor = plugin.getConfig().slotTimerBuyColor();
		}
		else
		{
			slotStateString = "Sell";
			spacer = SELL_SPACER;
			stateTextColor = plugin.getConfig().slotTimerSellColor();
		}

		Color timeColor = isSlotStagnant() ? CustomColors.OUTDATED_COLOR : Color.WHITE;

		if (clientOffer.getState() == GrandExchangeOfferState.CANCELLED_BUY || clientOffer.getState() == GrandExchangeOfferState.CANCELLED_SELL || clientOffer.getState() == GrandExchangeOfferState.BOUGHT || clientOffer.getState() == GrandExchangeOfferState.SOLD)
		{
			//Override to completion color
			timeColor = new Color(0, 180, 0);
		}

		if (timeString.length() > 9)
		{
			//Make sure we don't overflow the text
			timeString = "   --:--:--";
		}

		slotStateWidget.setText("  <html>" + ColorUtil.wrapWithColorTag(slotStateString, stateTextColor) + spacer + ColorUtil.wrapWithColorTag(timeString, timeColor) + "</html>");
	}

	/**
	 * Resets the offer state text to default Jagex format.
	 */
	public void resetToDefault()
	{
		try {
			if (!isSlotFilled())
			{
				slotStateWidget.setText("Empty");
			}
			else if (currentOffer.isBuy())
			{
				slotStateWidget.setText("Buy");
			}
			else if (!currentOffer.isBuy())
			{
				slotStateWidget.setText("Sell");
			}
			slotStateWidget.setFontId(496);
			slotStateWidget.setXTextAlignment(1);
		}
		catch (NullPointerException e) {
			log.debug("npe when resetting slot visuals. This is ok");
		}
	}

	/**
	 * Finds whether the slot is filled with an offer or if it's empty.
	 *
	 * @return Returns true if the slot is filled and false if it's empty.
	 */
	private boolean isSlotFilled()
	{
		GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		return offers[slotIndex].getItemId() != 0;
	}

	/**
	 * Returns whether the slot contains a stagnant offer as defined by the user config.
	 * Has to be run after createFormattedTimeString() else the timerBase won't be sufficiently up to date.
	 */
	private boolean isSlotStagnant()
	{
		return lastUpdate.isBefore(Instant.now().minus(plugin.getConfig().tradeStagnationTime(), ChronoUnit.MINUTES));
	}


	public String createFormattedTimeString()
	{
		if (currentOffer == null || tradeStartTime == null || lastUpdate == null || offerOccurredAtUnknownTime) {
			return null;
		}

		if (currentOffer.isComplete())
		{
			return TimeFormatters.formatDuration(tradeStartTime, lastUpdate);
		}

		else
		{
			return TimeFormatters.formatDuration(lastUpdate, Instant.now());
		}
	}
}

package com.flippingutilities.ui.widgets;

import com.flippingutilities.controller.FlippingPlugin;
import com.flippingutilities.jobs.TimeseriesFetcher;
import com.flippingutilities.ui.uiutilities.GeSpriteLoader;
import com.flippingutilities.utilities.SlotInfo;
import com.flippingutilities.utilities.SlotPredictedState;
import com.flippingutilities.utilities.WikiItemMargins;
import com.flippingutilities.utilities.WikiRequest;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.FontID;
import net.runelite.api.SpriteID;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.widgets.JavaScriptCallback;
import net.runelite.api.events.BeforeRender;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.api.widgets.WidgetPositionMode;
import net.runelite.api.widgets.WidgetSizeMode;
import net.runelite.api.widgets.WidgetTextAlignment;
import net.runelite.api.widgets.WidgetType;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.ui.overlay.tooltip.Tooltip;
import net.runelite.client.ui.overlay.tooltip.TooltipManager;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Optional;

/**
 * This class is responsible for enhancing slots in the GE interface by adding
 * color-coded borders and a "quick look" icon that displays a detailed tooltip on hover.
 * <p>
 * It is fed data (wiki margins, slot widgets) by the plugin. Upon receiving new data,
 * it builds a representation of what to draw and applies the visual enhancements.
 */
@Slf4j
public class SlotStateDrawer {

    private final FlippingPlugin plugin;
    private final Client client;
    private final TooltipManager tooltipManager;
    private final TimeseriesFetcher timeseriesFetcher;

    private WikiRequest wikiRequest;
    private Widget[] slotWidgets;
    private List<Optional<SlotInfo>> slotInfos = new ArrayList<>();
    private final Map<Integer, Widget> slotIdxToQuickLookWidget = new HashMap<>();

    private Integer hoveredSlotIndex = null;
    private QuickLookTooltip currentTooltip = null;
    private Integer currentlyFetchedItemId = null;

    public SlotStateDrawer(
            FlippingPlugin plugin,
            TooltipManager toolTipManager,
            Client client,
            TimeseriesFetcher timeseriesFetcher
    ) {
        this.plugin = plugin;
        this.client = client;
        this.tooltipManager = toolTipManager;
        this.timeseriesFetcher = timeseriesFetcher;
    }

    @Subscribe
    public void onBeforeRender(BeforeRender event) {
        if (hoveredSlotIndex == null || !plugin.shouldEnhanceSlots()) {
            currentTooltip = null;
            return;
        }

        final Widget geWindow = client.getWidget(InterfaceID.GeOffers.UNIVERSE);
        if (geWindow == null || geWindow.isHidden()) {
            hoveredSlotIndex = null;
            currentTooltip = null;
            return;
        }

        final Widget offerContainer = client.getWidget(
                InterfaceID.GeOffers.SETUP
        );
        if (offerContainer != null && !offerContainer.isHidden()) {
            hoveredSlotIndex = null;
            currentTooltip = null;
            return;
        }

        buildAndShowTooltip();
    }

    /**
     * Receives updated wiki margins and triggers a refresh of the slot visuals.
     */
    public void onWikiRequest(WikiRequest wikiRequest) {
        this.wikiRequest = wikiRequest;
        refreshSlotVisuals();
    }

    /**
     * Receives the GE slot widgets from the client and triggers a refresh.
     */
    public void setSlotWidgets(Widget[] slotWidgets) {
        if (slotWidgets == null) {
            return;
        }
        this.slotWidgets = slotWidgets;
        refreshSlotVisuals();
    }

    /**
     * Gatekeeper method to ensure all necessary conditions are met before drawing.
     */
    public void refreshSlotVisuals() {
        if (
                slotWidgets == null ||
                        plugin.getCurrentlyLoggedInAccount() == null ||
                        !plugin.getApiAuthHandler().isPremium() ||
                        !plugin.shouldEnhanceSlots()
        ) {
            return;
        }
        this.slotInfos = createSlotRepresentation();
        plugin.getClientThread().invokeLater(() -> draw(slotInfos));
    }

    /**
     * Draws the enhancements on all slots based on the generated SlotInfo.
     */
    private void draw(final List<Optional<SlotInfo>> slots) {
        for (int i = 0; i < slots.size(); i++) {
            final Optional<SlotInfo> slotOpt = slots.get(i);
            final Widget slotWidget = slotWidgets[i + 1];

            if (slotOpt.isPresent()) {
                drawOnSlot(slotOpt.get(), slotWidget);
            } else {
                resetSlot(i, slotWidget);
            }
        }
    }

    /**
     * Resets all visual enhancements on all slots.
     */
    public void resetAllSlots() {
        if (slotWidgets == null) {
            return;
        }
        for (int i = 0; i < 8; i++) {
            resetSlot(i, slotWidgets[i + 1]);
        }
    }

    /**
     * Reverts a single slot to its default appearance, hiding any enhancements.
     */
    private void resetSlot(int slotIdx, final Widget slotWidget) {
        // Revert borders to default color
        Map<Integer, Integer> spriteIdMap = GeSpriteLoader.CHILDREN_IDX_TO_DEFAULT_SPRITE_ID;
        GeSpriteLoader.DYNAMIC_CHILDREN_IDXS.forEach(idx -> {
            Widget child = slotWidget.getChild(idx);
            int spriteId = spriteIdMap.get(idx);
            if (child != null) {
                child.setSpriteId(spriteId);
            }
        });

        // Hide and remove the quick look widget
        Widget quickLookWidget = slotIdxToQuickLookWidget.remove(slotIdx);
        if (quickLookWidget != null) {
            quickLookWidget.setHidden(true);
        }
    }

    /**
     * Applies visual enhancements (colored border, quick look icon) to a slot.
     */
    private void drawOnSlot(final SlotInfo slot, final Widget slotWidget) {
        if (slotWidget.isHidden()) {
            return;
        }

        final Map<Integer, Integer> spriteMap = getSpriteMapForState(
                slot.getPredictedState()
        );

        GeSpriteLoader.DYNAMIC_CHILDREN_IDXS.forEach(idx -> {
            Widget child = slotWidget.getChild(idx);
            if (child != null) {
                child.setSpriteId(spriteMap.get(idx));
            }
        });

        addQuickLookWidget(slotWidget, slot);
    }

    /**
     * Gets the appropriate color-coded sprite map for the slot's predicted state.
     */
    private Map<Integer, Integer> getSpriteMapForState(
            SlotPredictedState state
    ) {
        switch (state) {
            case IN_RANGE:
                return GeSpriteLoader.CHILDREN_IDX_TO_BLUE_SPRITE_ID;
            case BETTER_THAN_WIKI:
                return GeSpriteLoader.CHILDREN_IDX_TO_GREEN_SPRITE_ID;
            case OUT_OF_RANGE:
            default:
                return GeSpriteLoader.CHILDREN_IDX_TO_RED_SPRITE_ID;
        }
    }

    /**
     * Adds or reveals the quick look (magnifying glass) icon on a slot.
     */
    private void addQuickLookWidget(Widget slotWidget, SlotInfo slot) {
        Widget existingWidget = slotIdxToQuickLookWidget.get(slot.getIndex());

        // Hide widget if quick lookup is disabled
        if (!plugin.getConfig().quickLookupEnabled()) {
            if (existingWidget != null) {
                existingWidget.setHidden(true);
            }
            return;
        }

        if (existingWidget == null || !isWidgetStillAttached(existingWidget)) {
            Widget newWidget = createQuickLookWidget(slotWidget, slot);
            slotIdxToQuickLookWidget.put(slot.getIndex(), newWidget);
        } else {
            existingWidget.setHidden(false);
        }
    }

    /**
     * Creates the quick look widget with its properties and mouse listeners.
     */
    private Widget createQuickLookWidget(Widget slotWidget, final SlotInfo slot) {
        Widget quickLookWidget = slotWidget.createChild(-1, WidgetType.GRAPHIC);
        quickLookWidget.setFontId(FontID.PLAIN_11);
        quickLookWidget.setOriginalX(90);
        quickLookWidget.setOriginalY(52);
        quickLookWidget.setSpriteId(SpriteID.BANK_SEARCH);
        quickLookWidget.setWidthMode(WidgetSizeMode.ABSOLUTE);
        quickLookWidget.setOriginalHeight(22);
        quickLookWidget.setOriginalWidth(22);
        quickLookWidget.setXPositionMode(WidgetPositionMode.ABSOLUTE_LEFT);
        quickLookWidget.setYPositionMode(WidgetPositionMode.ABSOLUTE_TOP);
        quickLookWidget.setXTextAlignment(WidgetTextAlignment.LEFT);
        quickLookWidget.setTextShadowed(true);
        quickLookWidget.setHasListener(true);

        // Set mouse listeners to control hover state and trigger data fetching
        quickLookWidget.setOnMouseOverListener(
                (JavaScriptCallback) ev -> {
                    this.hoveredSlotIndex = slot.getIndex();
                    if (currentlyFetchedItemId == null || !currentlyFetchedItemId.equals(slot.getItemId())) {
                        currentlyFetchedItemId = slot.getItemId();

                        if (plugin.getConfig().quickLookupEnabled()) {
                            timeseriesFetcher.fetch(slot.getItemId(), plugin.getConfig().priceGraphTimestep(), tsResponse -> {
                                if (hoveredSlotIndex == null || hoveredSlotIndex >= slotInfos.size()) {
                                    return;
                                }
                                if (tsResponse == null) {
                                    return;
                                }
                                if (currentTooltip == null) {
                                    currentTooltip = new QuickLookTooltip();
                                    Optional<SlotInfo> slotInfoOpt = slotInfos.get(hoveredSlotIndex);
                                    if (slotInfoOpt.isPresent()) {
                                        SlotInfo slotInfo = slotInfoOpt.get();
                                        if (wikiRequest != null && wikiRequest.getData() != null) {
                                            WikiItemMargins margins = wikiRequest.getData().get(slotInfo.getItemId());
                                            if (margins != null) {
                                                currentTooltip.update(slotInfo, margins);
                                            }
                                        }
                                    }
                                }
                                if (currentTooltip != null) {
                                    currentTooltip.setGraphData(tsResponse, plugin.getConfig().priceGraphTimestep(), slot.getOfferPrice());
                                }
                            });
                        }
                    }
                }
        );

        quickLookWidget.setOnMouseLeaveListener(
                (JavaScriptCallback) ev -> {
                    this.hoveredSlotIndex = null;
                    this.currentTooltip = null;
                    this.currentlyFetchedItemId = null;
                }
        );

        quickLookWidget.setOnClickListener(
                (JavaScriptCallback) ev -> this.hoveredSlotIndex = null
        );

        quickLookWidget.revalidate();
        return quickLookWidget;
    }

    /**
     * Checks if a widget is still valid and attached to its parent. This is crucial
     * for deciding whether to reuse an old widget or create a new one, especially
     * after client operations that might recreate widgets (like closing/opening the GE).
     */
    private boolean isWidgetStillAttached(Widget widget) {
        Widget parent = widget.getParent();
        if (parent == null) {
            return false;
        }
        Widget[] siblings = parent.getDynamicChildren();
        return (
                siblings != null &&
                        widget.getIndex() < siblings.length &&
                        siblings[widget.getIndex()] == widget
        );
    }

    /**
     * Creates a list of SlotInfo objects, which represent the state of each GE slot.
     * This abstracts the raw client and wiki data into a unified model for drawing.
     */
    private List<Optional<SlotInfo>> createSlotRepresentation() {
        List<Optional<SlotInfo>> slots = new ArrayList<>();
        GrandExchangeOffer[] currentOffers = client.getGrandExchangeOffers();

        for (int i = 0; i < currentOffers.length; i++) {
            GrandExchangeOffer localSlot = currentOffers[i];
            if (localSlot.getState() == GrandExchangeOfferState.EMPTY) {
                slots.add(Optional.empty());
            } else {
                slots.add(clientGeOfferToSlotInfo(i, localSlot));
            }
        }
        return slots;
    }

    /**
     * Converts a GrandExchangeOffer into a SlotInfo object using wiki margin data.
     */
    private Optional<SlotInfo> clientGeOfferToSlotInfo(
            int index,
            GrandExchangeOffer offer
    ) {
        if (wikiRequest == null || wikiRequest.getData() == null) {
            return Optional.empty();
        }

        int itemId = offer.getItemId();
        WikiItemMargins margins = this.wikiRequest.getData().get(itemId);
        if (margins == null) {
            return Optional.empty();
        }

        long listedPrice = offer.getPrice();
        GrandExchangeOfferState offerState = offer.getState();
        boolean isBuy = offerState == GrandExchangeOfferState.BUYING || offerState == GrandExchangeOfferState.BOUGHT;
        boolean isCompleted = offerState == GrandExchangeOfferState.BOUGHT || offerState == GrandExchangeOfferState.SOLD;
        SlotPredictedState predictedState = SlotPredictedState.getPredictedState(
                isBuy,
                listedPrice,
                margins.getLow(),
                margins.getHigh()
        );

        return Optional.of(
                new SlotInfo(index, predictedState, itemId, listedPrice, isBuy, isCompleted)
        );
    }

    private void buildAndShowTooltip() {
        if (hoveredSlotIndex >= slotInfos.size() || wikiRequest == null || wikiRequest.getData() == null) {
            return;
        }

        Optional<SlotInfo> slotInfoOpt = slotInfos.get(hoveredSlotIndex);
        if (!slotInfoOpt.isPresent()) {
            return;
        }

        SlotInfo slotInfo = slotInfoOpt.get();
        WikiItemMargins margins = wikiRequest.getData().get(slotInfo.getItemId());

        if (currentTooltip == null) {
            currentTooltip = new QuickLookTooltip();
        }
        currentTooltip.update(slotInfo, margins);

        tooltipManager.add(new Tooltip(currentTooltip));
    }

}

package com.flippingutilities.ui.widgets;

/**
 * calculates visually pleasing tick intervals for chart axes.
 * uses standard "nice numbers" to ensure readable tick values.
 */
public final class TickIntervalCalculator {

    /** standard nice numbers for tick intervals */
    private static final long[] NICE_NUMBERS = {1, 2, 5, 10};
    /** target number of ticks to display on chart axis */
    private static final int TARGET_TICK_COUNT = 6;

    public long calculate(long range) {
        long roughInterval = range / TARGET_TICK_COUNT;

        if (roughInterval <= 0) {
            return 1;
        }

        long magnitude = 1;
        while (magnitude <= roughInterval / 10) {
            magnitude *= 10;
        }

        if (roughInterval <= magnitude) {
            return magnitude;
        } else if (roughInterval <= 2 * magnitude) {
            return 2 * magnitude;
        } else if (roughInterval <= 2.5 * magnitude) {
            return magnitude * 2 + magnitude / 2;
        } else if (roughInterval <= 5 * magnitude) {
            return 5 * magnitude;
        } else {
            return 10 * magnitude;
        }
    }
}

package com.flippingutilities.ui.widgets;

import com.flippingutilities.model.Timestep;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;

public final class TimeLabelGenerator {

    private static final DateTimeFormatter HOUR_FORMATTER = DateTimeFormatter.ofPattern("HH:mm");
    private static final DateTimeFormatter DAY_FORMATTER = DateTimeFormatter.ofPattern("MMM dd");
    private static final DateTimeFormatter MONTH_FORMATTER = DateTimeFormatter.ofPattern("MMM");
    private static final DateTimeFormatter MONTH_YEAR_FORMATTER = DateTimeFormatter.ofPattern("MMM yy");

    public static String[] generate(Timestep timestep, long currentTimeSeconds) {
        int labelCount = timestep.getLabelCount();
        String[] labels = new String[labelCount];

        long rangeSeconds = timestep.getMaxTimeRangeSeconds();
        long intervalSeconds = rangeSeconds / (labelCount - 1);

        for (int i = 0; i < labelCount; i++) {
            long secondsAgo = rangeSeconds - (i * intervalSeconds);
            long timestamp = currentTimeSeconds - secondsAgo;
            labels[i] = formatTimestamp(timestamp, timestep);
        }

        return labels;
    }

    private static String formatTimestamp(long timestampSeconds, Timestep timestep) {
        Instant instant = Instant.ofEpochSecond(timestampSeconds);
        ZoneId zoneId = ZoneId.systemDefault();

        switch (timestep) {
            case FIVE_MINUTES:
                return HOUR_FORMATTER.format(instant.atZone(zoneId));
            case ONE_HOUR:
                return DAY_FORMATTER.format(instant.atZone(zoneId));
            case SIX_HOURS:
                return DAY_FORMATTER.format(instant.atZone(zoneId));
            case TWENTY_FOUR_HOURS:
                int timestampYear = instant.atZone(zoneId).getYear();
                int currentYear = Instant.now().atZone(zoneId).getYear();
                if (timestampYear == currentYear) {
                    return MONTH_FORMATTER.format(instant.atZone(zoneId));
                } else {
                    return MONTH_YEAR_FORMATTER.format(instant.atZone(zoneId));
                }
            default:
                return "";
        }
    }
}

package com.flippingutilities.ui.widgets;

import com.flippingutilities.model.Timestep;
import com.flippingutilities.model.TimeseriesPoint;
import com.flippingutilities.model.TimeseriesResponse;
import com.flippingutilities.ui.uiutilities.CustomColors;
import com.flippingutilities.ui.uiutilities.UIUtilities;
import com.flippingutilities.ui.widgets.chart.ChartBounds;
import com.flippingutilities.ui.widgets.chart.PriceRange;
import com.flippingutilities.ui.widgets.chart.TimeRange;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;
import lombok.extern.slf4j.Slf4j;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.util.ArrayList;
import java.util.List;

@Slf4j
public final class TimeSeriesChart implements LayoutableRenderableEntity {

    private static final int PRICE_RANGE_MARGIN_DIVISOR = 10;
    private static final int MIN_PRICE_MARGIN = 5;

    private static final int LABEL_PADDING = 5;
    private static final int OFFER_LABEL_OFFSET = 3;

    private static final float GRID_DASH_LENGTH = 2.0f;
    private static final float OFFER_LINE_DASH_LENGTH = 5.0f;
    private static final float STROKE_ROUND_MITER = 10.0f;
    private static final float HOVER_LINE_STROKE = 1.5f;

    private static final int DEFAULT_LEFT_PADDING = 38;

    private static final String OFFER_LABEL_TEXT = "Your offer";

    private final ChartConfig config;
    private final TickIntervalCalculator tickCalculator;

    private final Point position = new Point();
    private final Dimension dimension = new Dimension();

    // Mutable dimensions that can be updated by setPreferredSize
    private int mutableWidth;
    private int mutableHeight;

    private TimeseriesResponse timeseries;
    private Timestep timestep;
    private long offerPrice;
    private long maxTimeRangeSeconds; // Custom max time range (overrides timestep default)

    // Hover state for vertical line indicator
    private TimeseriesPoint hoveredPoint;

    // Hover state for horizontal price line indicator
    private Integer hoveredPriceY;

    public TimeSeriesChart(ChartConfig config) {
        this.config = config;
        this.tickCalculator = new TickIntervalCalculator();
        this.mutableWidth = config.getWidth();
        this.mutableHeight = config.getHeight();
    }

    @Override
    public Dimension render(Graphics2D g2d) {
        if (!hasData()) {
            return new Dimension();
        }

        setupRenderingHints(g2d);

        List<TimeseriesPoint> dataPoints = timeseries.getData();
        if (dataPoints.isEmpty()) {
            dimension.setSize(config.getWidth(), config.getHeight());
            return dimension;
        }

        List<TimeseriesPoint> filteredData = filterAndSortData(dataPoints);

        PriceRange priceRange = calculatePriceRange(filteredData);

        ChartBounds bounds = calculateChartBounds();

        priceRange = adjustPriceRange(priceRange);

        drawGrid(g2d, bounds, priceRange);
        drawDataSeries(g2d, bounds, priceRange, filteredData);
        drawOfferLine(g2d, bounds, priceRange);
        drawTimeLabels(g2d, bounds);
        drawHoverLine(g2d, bounds, filteredData);
        drawHorizontalPriceLine(g2d, bounds, priceRange);

        dimension.setSize(config.getWidth(), config.getHeight());
        return dimension;
    }

    private void setupRenderingHints(Graphics2D g2d) {
        g2d.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g2d.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
    }

    public List<TimeseriesPoint> filterAndSortData(List<TimeseriesPoint> dataPoints) {
        List<TimeseriesPoint> sorted = new ArrayList<>();

        // Only include points within the selected date range
        long currentTime = System.currentTimeMillis() / 1000;
        long minTimestamp = currentTime - maxTimeRangeSeconds;

        for (TimeseriesPoint point : dataPoints) {
            if (point.getTimestamp() >= minTimestamp) {
                sorted.add(point);
            }
        }

        // Insertion sort by timestamp
        for (int i = 1; i < sorted.size(); i++) {
            TimeseriesPoint key = sorted.get(i);
            int j = i - 1;
            while (j >= 0 && sorted.get(j).getTimestamp() > key.getTimestamp()) {
                sorted.set(j + 1, sorted.get(j));
                j--;
            }
            sorted.set(j + 1, key);
        }

        return sorted;
    }

    private PriceRange calculatePriceRange(List<TimeseriesPoint> dataPoints) {
        Long minPrice = null;
        Long maxPrice = null;

        for (TimeseriesPoint point : dataPoints) {
            if (point.getAvgHighPrice() != null) {
                long highPrice = point.getAvgHighPrice();
                maxPrice = maxPrice == null ? highPrice : Math.max(maxPrice, highPrice);
            }

            if (point.getAvgLowPrice() != null) {
                long lowPrice = point.getAvgLowPrice();
                minPrice = minPrice == null ? lowPrice : Math.min(minPrice, lowPrice);
            }
        }

        // If we only have one type of price, use it for both min and max
        // This handles cases where we only have instasell or only instabuy data
        if (minPrice == null && maxPrice != null) {
            minPrice = maxPrice;
        } else if (maxPrice == null && minPrice != null) {
            maxPrice = minPrice;
        } else if (minPrice == null && maxPrice == null) {
            // No data at all, use offer price for both
            minPrice = offerPrice;
            maxPrice = offerPrice;
        }

        // Expand range to include offer price
        maxPrice = Math.max(maxPrice, offerPrice);
        minPrice = Math.min(minPrice, offerPrice);

        return new PriceRange(minPrice, maxPrice);
    }

    private PriceRange adjustPriceRange(PriceRange original) {
        long range = original.getRange();
        long min = original.min;
        long max = original.max;

        // For very small prices (<100), start at 0
        // For larger prices, use a margin around the data
        if (min < 100 && range < 100) {
            // Small prices - start at 0
            max = Math.max(max + 2, 5);
            min = 0;
        } else {
            // Larger prices - add margin around the data range
            long margin = Math.max(range / PRICE_RANGE_MARGIN_DIVISOR, MIN_PRICE_MARGIN);
            // Padding is visual only; keep the viewport within the representable price range.
            max = max > Long.MAX_VALUE - margin ? Long.MAX_VALUE : max + margin;
            min = Math.max(0, min - margin);
        }

        return new PriceRange(min, max);
    }

    private ChartBounds calculateChartBounds() {
        int x = position.x + DEFAULT_LEFT_PADDING;
        int y = position.y + config.getTopPadding();
        int width = mutableWidth - DEFAULT_LEFT_PADDING - config.getRightPadding();
        int height = mutableHeight - config.getTopPadding() - config.getBottomPadding();

        return new ChartBounds(x, y, width, height);
    }

    private TimeRange calculateTimeRange(List<TimeseriesPoint> filteredData) {
        // Always use the full range anchored to current time
        // This ensures the x-axis spans the selected duration (e.g., 24h for 1d)
        // and data points are positioned correctly within that range
        long currentTime = System.currentTimeMillis() / 1000;
        long start = currentTime - maxTimeRangeSeconds;
        long range = maxTimeRangeSeconds;

        return new TimeRange(start, range);
    }

    private void drawGrid(Graphics2D g2d, ChartBounds bounds, PriceRange priceRange) {
        g2d.setColor(config.getGridColor());
        g2d.setStroke(new BasicStroke(config.getGridStroke(), BasicStroke.CAP_BUTT,
                BasicStroke.JOIN_MITER, STROKE_ROUND_MITER,
                new float[] { GRID_DASH_LENGTH, GRID_DASH_LENGTH }, 0.0f));

        g2d.setFont(config.getLabelFont());
        FontMetrics fm = g2d.getFontMetrics();

        drawHorizontalGridLines(g2d, bounds, priceRange, fm);
        drawVerticalGridLines(g2d, bounds);
    }

    private void drawHorizontalGridLines(Graphics2D g2d, ChartBounds bounds,
            PriceRange priceRange, FontMetrics fm) {
        long tickInterval = tickCalculator.calculate(priceRange.getRange());
        long startPrice = (priceRange.min / tickInterval) * tickInterval;
        int rightEdge = bounds.getRightEdge();

        for (long price = startPrice; price <= priceRange.max;) {
            if (price >= priceRange.min) {
                int lineY = calculateYPosition(price, bounds, priceRange);
                g2d.setColor(config.getGridColor());
                g2d.drawLine(bounds.x, lineY, rightEdge, lineY);

                String priceText = UIUtilities.quantityToRSDecimalStack(price, false);
                g2d.setColor(config.getLabelColor());
                int textWidth = fm.stringWidth(priceText);
                g2d.drawString(priceText, bounds.x - textWidth - LABEL_PADDING,
                        lineY + fm.getAscent() / 2);
            }
            if (priceRange.max - price < tickInterval) {
                break;
            }
            price += tickInterval;
        }
    }

    private void drawVerticalGridLines(Graphics2D g2d, ChartBounds bounds) {
        int bottomEdge = bounds.getBottomEdge();
        int divisions = timestep.getLabelCount() - 1;

        for (int i = 0; i <= divisions; i++) {
            int lineX = bounds.x + (i * bounds.width / divisions);
            g2d.setColor(config.getGridColor());
            g2d.drawLine(lineX, bounds.y, lineX, bottomEdge);
        }
    }

    private int calculateYPosition(long price, ChartBounds bounds, PriceRange priceRange) {
        int bottomEdge = bounds.getBottomEdge();
        long range = priceRange.getRange();
        // Scale to pixel coordinates without overflowing a long monetary range.
        return bottomEdge - (int) ((double) (price - priceRange.min) * bounds.height / range);
    }

    private void drawDataSeries(Graphics2D g2d, ChartBounds bounds,
            PriceRange priceRange, List<TimeseriesPoint> filteredData) {
        if (filteredData.isEmpty()) {
            return;
        }

        TimeRange timeRange = calculateTimeRange(filteredData);

        int dataSize = filteredData.size();
        int[] highX = new int[dataSize];
        int[] highY = new int[dataSize];
        int[] lowX = new int[dataSize];
        int[] lowY = new int[dataSize];
        int highCount = 0;
        int lowCount = 0;

        for (TimeseriesPoint point : filteredData) {
            long timeOffset = point.getTimestamp() - timeRange.start;
            float timePercent = timeRange.range > 0 ? (float) timeOffset / timeRange.range : 0.5f;
            int xPos = bounds.x + (int) (timePercent * bounds.width);

            if (point.getAvgHighPrice() != null) {
                long highPrice = point.getAvgHighPrice();
                highX[highCount] = xPos;
                highY[highCount] = calculateYPosition(highPrice, bounds, priceRange);
                highCount++;
            }

            if (point.getAvgLowPrice() != null) {
                long lowPrice = point.getAvgLowPrice();
                lowX[lowCount] = xPos;
                lowY[lowCount] = calculateYPosition(lowPrice, bounds, priceRange);
                lowCount++;
            }
        }

        drawFillBetweenLines(g2d, highX, highY, highCount, lowX, lowY, lowCount);

        g2d.setStroke(new BasicStroke(config.getLineStroke(),
                BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
        drawLine(g2d, highX, highY, highCount, config.getHighLineColor());
        drawLine(g2d, lowX, lowY, lowCount, config.getLowLineColor());
    }

    private void drawFillBetweenLines(Graphics2D g2d, int[] highX, int[] highY, int highCount,
            int[] lowX, int[] lowY, int lowCount) {
        if (highCount <= 1 || lowCount <= 1) {
            return;
        }

        int totalPoints = highCount + lowCount;
        int[] fillX = new int[totalPoints];
        int[] fillY = new int[totalPoints];

        System.arraycopy(highX, 0, fillX, 0, highCount);
        System.arraycopy(highY, 0, fillY, 0, highCount);

        for (int i = 0; i < lowCount; i++) {
            int idx = highCount + i;
            fillX[idx] = lowX[lowCount - 1 - i];
            fillY[idx] = lowY[lowCount - 1 - i];
        }

        g2d.setColor(config.getFillColor());
        g2d.fillPolygon(fillX, fillY, totalPoints);
    }

    private void drawLine(Graphics2D g2d, int[] xPoints, int[] yPoints, int count, java.awt.Color color) {
        if (count <= 1) {
            return;
        }

        g2d.setColor(color);
        for (int i = 0; i < count - 1; i++) {
            g2d.drawLine(xPoints[i], yPoints[i], xPoints[i + 1], yPoints[i + 1]);
        }
    }

    private void drawOfferLine(Graphics2D g2d, ChartBounds bounds, PriceRange priceRange) {
        int offerY = calculateYPosition(offerPrice, bounds, priceRange);

        g2d.setStroke(new BasicStroke(config.getReferenceStroke(), BasicStroke.CAP_BUTT,
                BasicStroke.JOIN_MITER, STROKE_ROUND_MITER,
                new float[] { OFFER_LINE_DASH_LENGTH, OFFER_LINE_DASH_LENGTH }, 0.0f));
        g2d.setColor(config.getReferenceLineColor());

        int rightEdge = bounds.getRightEdge();
        g2d.drawLine(bounds.x, offerY, rightEdge, offerY);

        g2d.setFont(config.getLabelFont());
        g2d.setColor(config.getReferenceLineColor());
        g2d.drawString(OFFER_LABEL_TEXT, bounds.x + LABEL_PADDING,
                offerY - OFFER_LABEL_OFFSET);
    }

    /**
     * Draws a vertical line at the hovered data point position.
     */
    private void drawHoverLine(Graphics2D g2d, ChartBounds bounds, List<TimeseriesPoint> filteredData) {
        if (hoveredPoint == null) {
            return;
        }
        if (filteredData.isEmpty()) {
            return;
        }

        TimeRange timeRange = calculateTimeRange(filteredData);
        long timeOffset = hoveredPoint.getTimestamp() - timeRange.start;
        float timePercent = timeRange.range > 0 ? (float) timeOffset / timeRange.range : 0.5f;
        int lineX = bounds.x + (int) (timePercent * bounds.width);

        lineX = Math.max(bounds.x, Math.min(lineX, bounds.x + bounds.width));

        int bottomEdge = bounds.getBottomEdge();

        g2d.setStroke(new BasicStroke(HOVER_LINE_STROKE, BasicStroke.CAP_BUTT,
                BasicStroke.JOIN_MITER, STROKE_ROUND_MITER,
                new float[] { 5.0f, 5.0f }, 0.0f));
        g2d.setColor(CustomColors.CHART_ACCENT);
        g2d.drawLine(lineX, bounds.y, lineX, bottomEdge);
    }

    /**
     * Sets the currently hovered data point for the vertical line indicator.
     */
    public void setHoveredPoint(TimeseriesPoint point) {
        this.hoveredPoint = point;
    }

    private void drawTimeLabels(Graphics2D g2d, ChartBounds bounds) {
        g2d.setColor(config.getLabelColor());
        g2d.setFont(config.getLabelFont());
        FontMetrics fm = g2d.getFontMetrics();

        int bottomY = position.y + config.getHeight() - LABEL_PADDING;
        long currentTimeSeconds = System.currentTimeMillis() / 1000;
        String[] timeLabels = TimeLabelGenerator.generate(timestep, currentTimeSeconds);
        int divisions = timestep.getLabelCount() - 1;

        for (int i = 0; i < timeLabels.length; i++) {
            int labelX = bounds.x + (i * bounds.width / divisions);
            String label = timeLabels[i];
            int labelWidth = fm.stringWidth(label);
            g2d.drawString(label, labelX - labelWidth / 2, bottomY);
        }
    }

    public void setDataSeries(TimeseriesResponse timeseries, Timestep timestep, long offerPrice,
            long maxTimeRangeSeconds) {
