package com.flippingutilities.db;

import com.flippingutilities.model.AccountData;
import com.flippingutilities.model.Flip;
import com.flippingutilities.model.FlippingItem;
import com.flippingutilities.model.HistoryManager;
import com.flippingutilities.model.OfferEvent;
import com.flippingutilities.utilities.Constants;
import com.flippingutilities.utilities.SlotState;
import com.google.gson.Gson;
import com.google.gson.JsonObject;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.events.GrandExchangeOfferChanged;
import org.junit.Rule;
import org.junit.Test;
import org.junit.rules.TemporaryFolder;

import java.io.File;
import java.lang.reflect.Proxy;
import java.nio.file.Files;
import java.time.Instant;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.UUID;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class LongPricePersistenceTest {
    private static final String ACCOUNT = "Long prices";
    private static final long BUY_PRICE = 3_000_000_001L;
    private static final long SELL_PRICE = 5_000_000_001L;
    private static final Instant TIME = Instant.parse("2026-01-01T00:00:00Z");

    @Rule
    public TemporaryFolder folder = new TemporaryFolder();

    @Test
    public void cloneAndCloudPayloadKeepExactPricesAndSpent() {
        OfferEvent offer = offer(true, BUY_PRICE, 3);
        assertEquals(BUY_PRICE, offer.getPreTaxPrice());
        assertEquals(BUY_PRICE, offer.clone().getListedPrice());
        assertEquals(BUY_PRICE * 3, offer.clone().getSpent());

        JsonObject payload = new Gson().toJsonTree(SlotState.fromOfferEvent(offer)).getAsJsonObject();
        assertTrue(payload.getAsJsonPrimitive("offerPrice").isNumber());
        assertEquals(BUY_PRICE, payload.get("offerPrice").getAsLong());
        assertEquals(BUY_PRICE * 3, payload.get("filledPrice").getAsLong());
        assertEquals(3, payload.get("filledQty").getAsInt());
        assertEquals(123L, new Gson().fromJson("{\"p\":123}", OfferEvent.class).getPreTaxPrice());
    }

    @Test
    public void jsonAndCsvKeepLongPrices() throws Exception {
        Gson gson = new Gson();
        AccountData fromJson = gson.fromJson(gson.toJson(account()), AccountData.class);
        fromJson.getTrades().forEach(item -> item.hydrate(70));
        assertMoney(fromJson);

        File csv = folder.newFile("export.csv");
        TradePersister.exportToCsv(csv, fromJson.getTrades(), "All time");
        String exported = Files.readString(csv.toPath());
        assertTrue(exported.contains(",3000000001,BOUGHT"));
        assertTrue(exported.contains(",4995000001,SOLD"));
        assertTrue(exported.contains("Total profit: 5985000000"));
    }

    @Test
    public void taxTotalsAndWeightedFlipPricesDoNotNarrowToInt() {
        OfferEvent oldTax = offer(false, SELL_PRICE, 1000);
        oldTax.setTime(Instant.ofEpochSecond(Constants.GE_TAX_START + 1));
        assertEquals(SELL_PRICE - Constants.GE_TAX_CAP, oldTax.getPrice());
        assertEquals(5_000_000_000L, oldTax.getTaxPaid());

        OfferEvent firstBuy = offer(true, BUY_PRICE, 1);
        OfferEvent secondBuy = offer(true, BUY_PRICE + 3, 2);
        secondBuy.setTime(TIME.plusSeconds(1));
        OfferEvent sale = offer(false, SELL_PRICE, 3);
        sale.setTime(TIME.plusSeconds(2));
        Flip flip = HistoryManager.getFlips(Arrays.asList(firstBuy, secondBuy, sale)).get(0);
        assertEquals(BUY_PRICE + 2, flip.getBuyPrice());
        assertEquals(SELL_PRICE - Constants.GE_TAX_CAP, flip.getSellPrice());
    }

    private AccountData account() {
        OfferEvent buy = offer(true, BUY_PRICE, 3);
        OfferEvent sell = offer(false, SELL_PRICE, 3);
        sell.setTime(TIME.plusSeconds(60));
        FlippingItem item = new FlippingItem(4151, "Abyssal whip", 70, ACCOUNT);
        item.setValidFlippingPanelItem(true);
        item.getHistory().setCompressedOfferEvents(Arrays.asList(buy, sell));
        AccountData account = new AccountData();
        account.setTrades(Collections.singletonList(item));
        return account;
    }

    private List<OfferEvent> offers(AccountData account) {
        return account.getTrades().get(0).getHistory().getCompressedOfferEvents();
    }

    private void assertMoney(AccountData account) {
        List<OfferEvent> offers = offers(account);
        assertEquals(BUY_PRICE, offers.get(0).getPreTaxPrice());
        assertEquals(SELL_PRICE, offers.get(1).getPreTaxPrice());
        assertEquals(15_000_000L, offers.get(1).getTaxPaid());
        assertEquals(5_985_000_000L, FlippingItem.getProfit(offers));
        Flip flip = HistoryManager.getFlips(offers).get(0);
        assertEquals(BUY_PRICE, flip.getBuyPrice());
        assertEquals(SELL_PRICE - Constants.GE_TAX_CAP, flip.getSellPrice());
    }

    @Test
    public void clientEventUsesTheFullMonetaryRangeSupportedByTheApi() throws Exception {
        boolean longApi = GrandExchangeOffer.class.getMethod("getSpent").getReturnType() == long.class
            && GrandExchangeOffer.class.getMethod("getPrice").getReturnType() == long.class;
        // Older RuneLite releases expose int amounts. New releases exercise values above
        // that range through this same client boundary; serialization tests always use longs.
        long price = longApi ? BUY_PRICE : 700_000_001L;
        int quantity = 3;
        GrandExchangeOffer offer = (GrandExchangeOffer) Proxy.newProxyInstance(
            GrandExchangeOffer.class.getClassLoader(), new Class<?>[]{GrandExchangeOffer.class},
            (proxy, method, args) -> {
                switch (method.getName()) {
                    case "getQuantitySold":
                    case "getTotalQuantity": return quantity;
                    case "getItemId": return 4151;
                    case "getPrice": return apiMoney(price, method.getReturnType());
                    case "getSpent": return apiMoney(price * quantity, method.getReturnType());
                    case "getState": return GrandExchangeOfferState.BOUGHT;
                    default: throw new UnsupportedOperationException(method.getName());
                }
            });
        GrandExchangeOfferChanged event = new GrandExchangeOfferChanged();
        event.setOffer(offer);
        event.setSlot(2);
        OfferEvent converted = OfferEvent.fromGrandExchangeEvent(event);
        assertEquals(price, converted.getPreTaxPrice());
        assertEquals(price, converted.getListedPrice());
        assertEquals(price * quantity, converted.getSpent());
    }

    private Object apiMoney(long value, Class<?> returnType) {
        if (returnType == long.class) {
            return value;
        }
        return Math.toIntExact(value);
    }

    private OfferEvent offer(boolean buy, long price, int quantity) {
        return new OfferEvent(UUID.randomUUID().toString(), buy, 4151, quantity, price, TIME,
            2, buy ? GrandExchangeOfferState.BOUGHT : GrandExchangeOfferState.SOLD,
            10, 10, quantity, null, false, ACCOUNT, null, price, price * quantity);
    }
}

package com.flippingutilities.jobs;

import okhttp3.*;
import okio.Buffer;
import okio.BufferedSource;
import okio.Timeout;

import java.io.IOException;
import java.util.ArrayList;
import java.util.List;

/** Controlled HTTP boundary; requests never reach a socket. */
public class ManualClient extends OkHttpClient {
    public final List<ManualCall> calls = new ArrayList<>();
    @Override public Call newCall(Request request) {
        ManualCall call = new ManualCall(request);
        calls.add(call);
        return call;
    }

    public static class ManualCall implements Call {
        private final Request request;
        private Callback callback;
        private boolean canceled;
        ManualCall(Request request) { this.request = request; }
        public TrackingBody respond(int status, String text) throws IOException {
            TrackingBody body = new TrackingBody(text);
            callback.onResponse(this, new Response.Builder().request(request).protocol(Protocol.HTTP_1_1)
                .code(status).message("test response").body(body).build());
            return body;
        }
        public void fail() { callback.onFailure(this, new IOException("offline")); }
        @Override public Request request() { return request; }
        @Override public Response execute() { throw new AssertionError("Unexpected synchronous HTTP call"); }
        @Override public void enqueue(Callback callback) { this.callback = callback; }
        @Override public void cancel() { canceled = true; }
        @Override public boolean isExecuted() { return callback != null; }
        @Override public boolean isCanceled() { return canceled; }
        @Override public Timeout timeout() { return new Timeout(); }
        @Override public Call clone() { return new ManualCall(request); }
    }

    public static class TrackingBody extends ResponseBody {
        private final Buffer buffer = new Buffer();
        public boolean closed;
        TrackingBody(String text) { buffer.writeUtf8(text); }
        @Override public MediaType contentType() { return MediaType.parse("application/json"); }
        @Override public long contentLength() { return -1; }
        @Override public BufferedSource source() { return buffer; }
        @Override public void close() { closed = true; super.close(); }
    }
}

package com.flippingutilities.jobs;

import com.flippingutilities.FlippingConfig;
import com.flippingutilities.controller.FlippingPlugin;
import com.flippingutilities.model.CachedTimeseries;
import com.flippingutilities.model.Timestep;
import com.flippingutilities.model.TimeseriesResponse;
import com.flippingutilities.ui.widgets.OfferGraphChartOverlay.GraphDuration;
import com.google.gson.Gson;
import okhttp3.HttpUrl;
import org.junit.Test;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

import static org.junit.Assert.*;

public class TimeseriesFetcherTest {
    @Test
    public void persistedTimeRangesRequestEquivalentV2Lookbacks() {
        String[] persistedNames = {"FIVE_MINUTES", "ONE_HOUR", "SIX_HOURS", "TWENTY_FOUR_HOURS"};
        String[] lookbacks = {"24h", "7d", "30d", "1y"};
        GraphDuration[] durations = {GraphDuration.ONE_DAY, GraphDuration.ONE_WEEK,
            GraphDuration.ONE_MONTH, GraphDuration.ONE_YEAR};
        ManualClient client = new ManualClient();
        TimeseriesFetcher fetcher = fetcher(client);

        for (int i = 0; i < persistedNames.length; i++) {
            Timestep timestep = Timestep.valueOf(persistedNames[i]);
            assertEquals(durations[i], GraphDuration.fromTimestep(timestep));
            assertEquals(timestep, durations[i].getTimestep());
            assertEquals(durations[i].getMaxTimeRangeSeconds(), timestep.getMaxTimeRangeSeconds());
            fetcher.fetch(4151, timestep, response -> fail("No response has been delivered"));
            HttpUrl url = client.calls.get(i).request().url();
            assertEquals("https", url.scheme());
            assertEquals("prices.runescape.wiki", url.host());
            assertEquals("/api/v2/osrs/timeseries", url.encodedPath());
            assertEquals(lookbacks[i], url.queryParameter("lookback"));
            assertEquals("4151", url.queryParameter("id"));
            assertNull(url.queryParameter("timestep"));
        }
        assertEquals(Timestep.FIVE_MINUTES, new FlippingConfig() {}.priceGraphTimestep());
    }

    @Test
    public void responseMetadataAndLongPricesSurviveCachingByItemAndLookback() throws Exception {
        ManualClient client = new ManualClient();
        TimeseriesFetcher fetcher = fetcher(client);
        List<TimeseriesResponse> received = new ArrayList<>();
        fetcher.fetch(4151, Timestep.FIVE_MINUTES, received::add);
        assertTrue(client.calls.get(0).respond(200,
            "{\"itemId\":4151,\"startTimestamp\":100,\"endTimestamp\":200,\"timestep\":300,"
                + "\"data\":[{\"timestamp\":150,\"avgHighPrice\":5000000001.75,\"avgLowPrice\":null}]}").closed);
        assertEquals(1, received.size());
        TimeseriesResponse response = received.get(0);
        assertEquals(Long.valueOf(4151), response.getItemId());
        assertEquals(Long.valueOf(100), response.getStartTimestamp());
        assertEquals(Long.valueOf(200), response.getEndTimestamp());
        assertEquals(Long.valueOf(300), response.getTimestep());
        assertEquals(Long.valueOf(5_000_000_001L), response.getData().get(0).getAvgHighPrice());
        assertNull(response.getData().get(0).getAvgLowPrice());

        fetcher.fetch(4151, Timestep.FIVE_MINUTES, received::add);
        assertEquals(1, client.calls.size());
        assertSame(response, received.get(1));
        fetcher.fetch(4151, Timestep.ONE_HOUR, received::add);
        fetcher.fetch(4152, Timestep.FIVE_MINUTES, received::add);
        assertEquals(3, client.calls.size());
        assertEquals(2, received.size());
    }

    @Test
    public void failedResponseIsClosedAndRetriedWithoutCaching() throws Exception {
        ManualClient client = new ManualClient();
        TimeseriesFetcher fetcher = fetcher(client);
        List<TimeseriesResponse> received = new ArrayList<>();
        fetcher.fetch(4151, Timestep.FIVE_MINUTES, received::add);
        assertTrue(client.calls.get(0).respond(404, "Not found").closed);
        fetcher.fetch(4151, Timestep.FIVE_MINUTES, received::add);
        assertEquals(2, client.calls.size());
        assertTrue(received.isEmpty());
    }

    @Test
    public void cacheUsesReturnedSpacingAndFallsBackWhenItIsMissingOrInvalid() {
        Instant fetched = Instant.now().minusSeconds(3600);
        // A large server interval avoids sensitivity to the current wall-clock boundary.
        assertFalse(cached(fetched, Long.MAX_VALUE / 2).isStale());
        assertTrue(cached(fetched, 1L).isStale());
        assertTrue(cached(fetched, null).isStale());
        assertTrue(cached(fetched, 0L).isStale());
        assertTrue(cached(fetched, -1L).isStale());
    }

    private CachedTimeseries cached(Instant fetched, Long interval) {
        TimeseriesResponse response = new TimeseriesResponse(Collections.emptyList(), 4151L,
            100L, 200L, interval);
        return new CachedTimeseries(response, fetched, Timestep.FIVE_MINUTES);
    }

    private TimeseriesFetcher fetcher(ManualClient client) {
        FlippingPlugin plugin = new FlippingPlugin();
        plugin.gson = new Gson();
        return new TimeseriesFetcher(client, plugin);
    }
}

package com.flippingutilities.jobs;

import com.flippingutilities.controller.FlippingPlugin;
